  "inlineSchema": "// schema.prisma\n// Schema pentru magazin online gresie/produse - catalog, cos, comenzi, conturi client\n// Stiva: Next.js 16 + TypeScript + Prisma ORM + PostgreSQL (Neon) + Vercel\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============ UTILIZATORI SI AUTENTIFICARE ============\n\nmodel User {\n  id            String    @id @default(cuid())\n  email         String    @unique\n  emailVerified DateTime?\n  passwordHash  String? // null daca autentificare doar prin magic link / OAuth\n  firstName     String\n  lastName      String\n  phone         String?\n  role          UserRole  @default(CUSTOMER)\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  addresses Address[]\n  orders    Order[]\n  cart      Cart?\n  reviews   Review[]\n  wishlist  WishlistItem[]\n\n  @@index([email])\n}\n\nenum UserRole {\n  CUSTOMER\n  ADMIN\n}\n\nmodel Address {\n  id         String   @id @default(cuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label      String // ex: \"Acasa\", \"Santier\"\n  street     String\n  city       String\n  county     String\n  postalCode String\n  isDefault  Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  orders Order[]\n\n  @@index([userId])\n}\n\n// ============ CATALOG ============\n\nmodel Category {\n  id       String     @id @default(cuid())\n  slug     String     @unique\n  name     String\n  parentId String?\n  parent   Category?  @relation(\"CategoryToCategory\", fields: [parentId], references: [id])\n  children Category[] @relation(\"CategoryToCategory\")\n  products Product[]\n\n  seoTitle       String?\n  seoDescription String?\n\n  @@index([parentId])\n}\n\nmodel Product {\n  id          String   @id @default(cuid())\n  slug        String   @unique\n  name        String\n  description String   @db.Text\n  categoryId  String\n  category    Category @relation(fields: [categoryId], references: [id])\n\n  finish   String? // mat, lucios, antiderapant\n  material String  @default(\"Gresie portelanata rectificata\")\n  featured Boolean @default(false)\n  isActive Boolean @default(true)\n\n  seoTitle       String?\n  seoDescription String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  variants ProductVariant[]\n  images   ProductImage[]\n  reviews  Review[]\n  wishlist WishlistItem[]\n\n  @@index([categoryId])\n  @@index([slug])\n}\n\n// O varianta = o combinatie dimensiune/finisaj cu pret si stoc propriu\nmodel ProductVariant {\n  id          String  @id @default(cuid())\n  productId   String\n  product     Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  size        String // ex: \"30x60\", \"60x60\"\n  pricePerSqm Decimal @db.Decimal(10, 2)\n  sqmPerBox   Decimal @db.Decimal(6, 3) // ex: 1.44 mp/cutie\n  stockBoxes  Int     @default(0)\n  sku         String  @unique\n\n  cartItems  CartItem[]\n  orderItems OrderItem[]\n\n  @@index([productId])\n}\n\nmodel ProductImage {\n  id        String  @id @default(cuid())\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  url       String\n  altText   String?\n  position  Int     @default(0)\n\n  @@index([productId])\n}\n\nmodel Review {\n  id        String   @id @default(cuid())\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  rating    Int // 1-5\n  comment   String?  @db.Text\n  createdAt DateTime @default(now())\n\n  @@index([productId])\n}\n\nmodel WishlistItem {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@unique([userId, productId])\n}\n\n// ============ COS DE CUMPARATURI ============\n// Cos legat de user (client logat) - pentru guest checkout, cosul se tine\n// in cookie/session pe server si se leaga de user doar la autentificare.\n\nmodel Cart {\n  id         String     @id @default(cuid())\n  userId     String?    @unique\n  user       User?      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  guestToken String?    @unique // folosit pentru cos de vizitator, inainte de autentificare\n  items      CartItem[]\n  updatedAt  DateTime   @updatedAt\n}\n\nmodel CartItem {\n  id        String         @id @default(cuid())\n  cartId    String\n  cart      Cart           @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  variantId String\n  variant   ProductVariant @relation(fields: [variantId], references: [id])\n  boxes     Int // cantitate in cutii, deja rotunjita din mp dorit\n  createdAt DateTime       @default(now())\n\n  @@unique([cartId, variantId])\n}\n\n// ============ COMENZI ============\n\nmodel Order {\n  id          String   @id @default(cuid())\n  orderNumber String   @unique // ex: \"4521\"\n  userId      String?\n  user        User?    @relation(fields: [userId], references: [id])\n  guestEmail  String? // pentru guest checkout\n  addressId   String?\n  address     Address? @relation(fields: [addressId], references: [id])\n\n  status         OrderStatus @default(PENDING)\n  deliveryMethod String // \"curier\" | \"ridicare_depozit\"\n  subtotal       Decimal     @db.Decimal(10, 2)\n  deliveryFee    Decimal     @default(0) @db.Decimal(10, 2)\n  total          Decimal     @db.Decimal(10, 2)\n\n  paymentMethod String // \"card\" | \"ramburs\"\n  paymentStatus String  @default(\"pending\") // pending | paid | failed\n  invoiceUrl    String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  items OrderItem[]\n\n  @@index([userId])\n  @@index([status])\n  @@index([orderNumber])\n}\n\nenum OrderStatus {\n  PENDING\n  CONFIRMED\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  CANCELLED\n}\n\nmodel OrderItem {\n  id          String         @id @default(cuid())\n  orderId     String\n  order       Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  variantId   String\n  variant     ProductVariant @relation(fields: [variantId], references: [id])\n  boxes       Int\n  pricePerSqm Decimal        @db.Decimal(10, 2) // pret salvat la momentul comenzii\n  sqmPerBox   Decimal        @db.Decimal(6, 3)\n  lineTotal   Decimal        @db.Decimal(10, 2)\n\n  @@index([orderId])\n}\n",
